  [426157] = { "与えるすべてのHolyダメージが$N1%増加し、近接攻撃と呪文のクリティカルによりExorcismの呪文の残りクールダウンが$D1短縮されます。", nil, 0xc4a882f0, nil, "um" },
  [426162] = { nil, "$D1ごとに$N1回復します。", nil, 0x15b97dff, "mu" },
  [426173] = { "Judgementの射程が$N1ヤード延び、すべての呪文の呪文命中率が$N2%上昇します。", nil, 0xe1aed3a5, nil, "um" },
  [426174] = { "Malleable Protectionのアビリティを得ます：\n\n$I1\nDivine Protectionの間も行動できるようになり、効果時間が$N1%延長されますが、無敵になる代わりに受けるダメージを$N2%減少させるだけになります。さらに、Holy Shieldを使用すると、防御スキルが$N4を超えるポイントごとにAttack Powerを$N3得て、$D1持続します。", nil, 0x00244963, nil, "um" },
  [426175] = { "ベルトにMalleable Protectionのルーンを刻みます：\n\n$I1\nDivine Protection中も行動できるようになり、その効果時間が$N1%延長されますが、無敵になる代わりに受けるダメージを$N2%軽減するだけになります。さらに、Holy Shieldを発動すると、$N4を超える防御スキルのポイントごとにAttack Powerを$N3得ます。効果時間は$D1です。", nil, 0x523ac40a, nil, "um" },
  [426179] = { "Infusion of Lightのアビリティを得ます：\n\n$I1\nHoly ShockとFlash of Lightのクリティカルヒットにより、$D1以内に詠唱する次のHoly Lightの詠唱時間が$D2短縮されます。", nil, 0x58b745f4, nil, "um" },
  [426180] = { "ベルトにInfusion of Lightのルーンを刻みます：\n\n$I1\nHoly ShockとFlash of Lightのクリティカルヒットにより、$D1以内に詠唱する次のHoly Lightの詠唱時間が$D2短縮されます。", nil, 0x4905da9b, nil, "um" },
  [426192] = { nil, "そもそもmurlocに水中呼吸なんて必要なのでしょうか？", nil, 0x90149cf9, "mu" },
  [426195] = { "使用すると、$D1の間一時的に最大体力が$N1%増加します。効果が切れると、得た体力は失われます。さらに、Metamorphosis中はVengeanceによって翼で落下速度が遅くなります。", "Metamorphosis中は、体力が最大値の$N1%増加し、落下速度が遅くなります。", 0x56419bc8, 0x7d0d7712, "uu" },
  [426199] = { "$D1ごとに$N1のShadowダメージを与えます。", "$D1ごとに$N1のShadowダメージを受けます。", 0x89116fee, 0x89116fee, "uu" },
  [426243] = { "Corruption、Immolate、Curse of Agony、Unstable Affliction、Shadowflame、Siphon Lifeを付与すると、その呪文の継続ダメージ1回分に等しいダメージを対象に即座に与えます。残り時間が$N1秒未満のときにそれらの呪文をかけ直すと、その呪文の残りの継続ダメージに等しいダメージを対象に即座に与えます。", nil, 0x744ce5b3, nil, "um" },
  [426257] = { nil, "ひらめきに満ちています。", nil, 0x12978998, "mu" },
  [426301] = { "自分または召喚した悪魔が与えるダメージは、$N1%の確率で、もう一方が与えるダメージを$D1の間$N2%増加させます。", "あなたか召喚した悪魔が与えるダメージに、$N1%の確率で、もう一方が与えるダメージを$D1の間$N2%増加させる効果があります。", 0x68930328, 0x68930328, "uu" },
  [426303] = { "与えるすべてのダメージが$N1%増加します。", "与えるすべてのダメージが$N1%増加します。", 0xbb0dd240, 0xbb0dd240, "uu" },
  [426311] = { "与えるすべてのFireダメージが$N1%増加します。", "与えるすべてのFireダメージが$N1%増加します。", 0x7f6cf186, 0x7ff627f2, "uu" },
  [426316] = { "Conflagrateで敵に命中させると、$D1の間与えるすべてのShadowダメージが$N1%増加し、Shadowburnで敵に命中させると、$D2の間与えるすべてのFireダメージが$N3%増加します。さらに、Conflagrateは$N5%の確率でImmolateを消費せず、Shadowburnは$N6%の確率でSoul Shardを即座に返還します。", nil, 0xa8ba88f4, nil, "um" },
  [426320] = { "敵を燃やして$N1のShadowflameダメージを与え、さらに$D1かけて$N2の追加Shadowflameダメージを与えます。\n\nShadowflameはImmolate、またはAffliction、Destruction、Fire、Shadowの呪文を変化させる、またはそれらと相互作用するすべての効果を発動させ、その恩恵を受けますが、一体の対象にウォーロック一人がかけられるのはImmolateとShadowflameのどちらか一つだけです。さらに、ShadowflameはImproved Shadow Boltのタレントを発動させることができ、そのチャージを$N4回追加します。", "$N2秒ごとに$N1のShadowflameダメージを受けます。", 0xae243044, 0x0b858fca, "uu" },
  [426325] = { nil, "$N2秒ごとに$N1のFireダメージを受けます。", nil, 0x341a73be, "mu" },
  [426359] = { "Comprehension Charmで呪文のメモを解読し、新しいEngraving呪文を習得します。", nil, 0x7ccaad21, nil, "um" },
  [426442] = { "Invocationのアビリティを得ます：\n\n$I1\nCorruption、Immolate、Curse of Agony、Unstable Affliction、Shadowflame、Siphon Lifeを付与すると、その呪文の継続ダメージ1回分に等しいダメージを対象に即座に与えます。残り時間が$N1秒未満のときにそれらの呪文をかけ直すと、その呪文の残りの継続ダメージに等しいダメージを対象に即座に与えます。", nil, 0x4bcef489, nil, "um" },
  [426443] = { "ベルトにInvocationのルーンを刻みます：\n\n$I1\nCorruption、Immolate、Curse of Agony、Unstable Affliction、Shadowflame、Siphon Lifeを付与すると、その呪文の持続ダメージ一回分に等しい即時ダメージを対象に与えます。残り時間が$N1秒未満のときにこれらの呪文を更新すると、その呪文の残りの持続ダメージに等しい即時ダメージを対象に与えます。", nil, 0xf02be364, nil, "um" },
  [426444] = { "Grimoire of Synergyのアビリティを得ます：\n\n$I1\n自分または召喚した悪魔がダメージを与えると、$N1%の確率で、$D1の間もう一方の与えるダメージが$N2%増加します。", nil, 0xed3c384e, nil, "um" },
  [426445] = { "ベルトにGrimoire of Synergyのルーンを刻みます：\n\n$I1\n自分または召喚した悪魔が与えるダメージは、$N1%の確率で、もう一方が与えるダメージを$D1の間$N2%増加させます。", nil, 0x6962f950, nil, "um" },
  [426449] = { "Shadow and Flameのアビリティを得ます：\n\n$I1\nConflagrateで敵を攻撃すると$D1の間、与えるすべてのShadowダメージが$N1%増加し、Shadowburnで敵を攻撃すると$D2の間、与えるすべてのFireダメージが$N3%増加します。さらに、Conflagrateは$N5%の確率でImmolateを消費せず、Shadowburnは$N6%の確率でSoul Shardを即座に返還します。", nil, 0xac371e1e, nil, "um" },
  [426452] = { "ベルトにShadow and Flameのルーンを刻みます：\n\n$I1\nConflagrateで敵に命中させると、$D1の間与えるShadowダメージがすべて$N1%増加し、Shadowburnで敵に命中させると、$D2の間与えるFireダメージがすべて$N3%増加します。さらに、Conflagrateは$N5%の確率でImmolateを消費せず、Shadowburnは$N6%の確率でSoul Shardを即座に返還します。", nil, 0x6e71e40a, nil, "um" },
  [426454] = { "Shadowflameのアビリティを得ます：\n\n$I1\n敵を焼き、$N1のShadowflameダメージを与え、さらに$D1かけて$N2のShadowflameダメージを与えます。\n\nShadowflameは、Immolate、またはAffliction、Destruction、Fire、Shadowの呪文を強化したりそれらと連動したりするすべての効果を発動させ、その恩恵を受けますが、どの対象にもウォーロック一人につきImmolateとShadowflameのどちらか一方しか有効にできません。さらに、ShadowflameはImproved Shadow Boltの才能を発動させることができ、そのチャージを$N4回追加します。", nil, 0x0c00a94d, nil, "um" },
  [426467] = { "ブーツにShadowflameのルーンを刻みます：\n\n$I1\n敵を焼き、$N1のShadowflameダメージを与え、さらに$D1かけて$N2のShadowflameダメージを与えます。\n\nShadowflameは、Immolate、またはAffliction、Destruction、Fire、Shadowの呪文を変化させる、もしくはそれらと相互作用するすべての効果を発動させ、その恩恵を受けますが、一つの対象に対してウォーロックごとに有効にできるのはImmolateとShadowflameのどちらか一方だけです。さらに、ShadowflameはImproved Shadow Boltタレントを発動させることができ、その場合チャージが$N4追加されます。", nil, 0xc47d2fb0, nil, "um" },
  [426469] = { "Vengeanceのアビリティを得ます：\n\n$I1\n使用すると、$D1の間、最大体力が一時的に$N1%増加します。効果が切れると、その体力は失われます。さらに、Metamorphosisの間は、Vengeanceによって翼で落下速度が遅くなります。", nil, 0x170741ae, nil, "um" },
  [426470] = { "頭部にVengeanceのルーンを刻みます：\n\n$I1\n発動すると、$D1の間、最大体力が一時的に$N1%増加します。効果が切れると、その体力は失われます。さらに、Metamorphosis中は、Vengeanceにより翼で落下速度が遅くなります。", nil, 0xb6b931d6, nil, "um" },
  [426489] = { nil, "与えるすべてのダメージが$N1%増加します。", nil, 0xd6406ebb, "mu" },
