  [426491] = { "ブーツにRallying Cryのルーンを刻みます：\n\n$I1\n鼓舞の雄叫びを上げ、$N1ヤード以内のパーティーとレイドのメンバー全員の最大体力を$D1の間$N2%増加させます。", nil, 0xec8cc0d9, nil, "um" },
  [426492] = { "Rallying Cryのアビリティを得ます：\n\n$I1\n鼓舞の叫びを上げ、$N1ヤード以内のすべてのパーティーとレイドのメンバーの最大体力を$D1の間$N2%増加させます。", nil, 0x04519817, nil, "um" },
